changeSet.rollback:
DELETE FROM transactions
WHERE account_id IN (
    SELECT a.id
    FROM accounts a
    JOIN clients c ON c.id = a.client_id
    WHERE c.email LIKE 'client-%@test.local'
      AND a.account_number LIKE 'ACC-%'
);

DELETE FROM accounts
WHERE account_number LIKE 'ACC-%'
  AND client_id IN (SELECT id FROM clients WHERE email LIKE 'client-%@test.local');

DELETE FROM clients
WHERE email LIKE 'client-%@test.local';
